import { Request, Response, Router } from 'express';
import { z } from 'zod';
import { v4 as uuidv4 } from 'uuid';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';
import { CursorQuerySchema, paginate, pageSchema } from '../lib/pagination.ts';
import { idempotency } from '../lib/idempotency.ts';

export const UserRoleSchema = z.enum(['admin', 'member']);
export type UserRole = z.infer<typeof UserRoleSchema>;

export const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});
export type User = z.infer<typeof UserSchema>;

export const CreateUserSchema = z.object({
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema.default('member'),
});

export const UpdateUserSchema = z.object({
  email: z.string().email().optional(),
  name: z.string().min(1).max(100).optional(),
  role: UserRoleSchema.optional(),
}).refine((data) => Object.keys(data).length > 0, {
  message: 'At least one field must be provided for update',
});

const users = new Map<string, User>();

export const usersRouter = Router();

usersRouter.get('/', (req, res) => {
  const query = CursorQuerySchema.parse(req.query);
  const allUsers = Array.from(users.values());
  const { data, nextCursor } = paginate(allUsers, query, (u) => `${u.createdAt}|${u.id}`);
  res.json(pageSchema(UserSchema).parse({ data, nextCursor }));
});

usersRouter.get('/:id', (req, res) => {
  const id = z.string().uuid().parse(req.params.id);
  const user = users.get(id);
  if (!user) throw notFound(`User with id ${id} not found`);
  res.json(UserSchema.parse(user));
});

usersRouter.post('/', idempotency(), (req, res) => {
  const input = CreateUserSchema.parse(req.body);
  const emailExists = Array.from(users.values()).some((u) => u.email === input.email);
  if (emailExists) throw conflict(`User with email ${input.email} already exists`);

  const id = uuidv4();
  const now = new Date().toISOString();
  const user: User = {
    id,
    ...input,
    createdAt: now,
    updatedAt: now,
  };
  users.set(id, user);
  res.status(201).location(`/v1/users/${id}`).json(UserSchema.parse(user));
});

usersRouter.patch('/:id', (req, res) => {
  const id = z.string().uuid().parse(req.params.id);
  const user = users.get(id);
  if (!user) throw notFound(`User with id ${id} not found`);

  const input = UpdateUserSchema.parse(req.body);
  const email = input.email ?? user.email;
  const emailConflict = Array.from(users.values()).some((u) => u.id !== id && u.email === email);
  if (emailConflict) throw conflict(`User with email ${email} already exists`);

  const updatedUser: User = {
    ...user,
    ...input,
    updatedAt: new Date().toISOString(),
  };
  users.set(id, updatedUser);
  res.json(UserSchema.parse(updatedUser));
});

usersRouter.delete('/:id', (req, res) => {
  const id = z.string().uuid().parse(req.params.id);
  if (!users.has(id)) throw notFound(`User with id ${id} not found`);
  users.delete(id);
  res.status(204).send();
});

