import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { createApp } from '../src/app';
import { v4 as uuidv4 } from 'uuid';

describe('Users API', () => {
  let app: any;

  beforeEach(() => {
    app = request(createApp());
  });

  describe('POST /v1/users', () => {
    it('creates a user and returns 201', async () => {
      const res = await app.post('/v1/users').send({
        email: 'test@example.com',
        name: 'Test User',
      });

      expect(res.status).toBe(201);
      expect(res.headers.location).toMatch(/\/v1\/users\/[a-f0-9-]{36}$/);
      expect(res.body).toMatchObject({
        email: 'test@example.com',
        name: 'Test User',
        role: 'member',
      });
      expect(res.body.id).toBeDefined();
      expect(res.body.createdAt).toBeDefined();
      expect(res.body.updatedAt).toBeDefined();
    });

    it('defaults role to member', async () => {
      const res = await app.post('/v1/users').send({
        email: 'role@example.com',
        name: 'Role User',
      });
      expect(res.body.role).toBe('member');
    });

    it('returns 409 if email already exists', async () => {
      const user = { email: 'dup@example.com', name: 'Dup' };
      await app.post('/v1/users').send(user);
      const res = await app.post('/v1/users').send(user);
      expect(res.status).toBe(409);
      expect(res.body.type).toBe('https://api.sf/problems/conflict');
    });

    it('returns 422 for invalid input', async () => {
      const res = await app.post('/v1/users').send({
        email: 'not-an-email',
        name: '',
      });
      expect(res.status).toBe(422);
      expect(res.body.detail).toBeDefined();
    });

    it('returns 400 for malformed JSON', async () => {
      const res = await app.post('/v1/users')
        .set('Content-Type', 'application/json')
        .send('{"invalid": json}');
      expect(res.status).toBe(400);
    });

    it('honours Idempotency-Key', async () => {
      const user = { email: 'idem@example.com', name: 'Idem' };
      const key = 'idem-key-1';

      const res1 = await app.post('/v1/users')
        .set('Idempotency-Key', key)
        .send(user);

      expect(res1.status).toBe(201);
      const userId = res1.body.id;

      const res2 = await app.post('/v1/users')
        .set('Idempotency-Key', key)
        .send(user);

      expect(res2.status).toBe(201);
      expect(res2.body.id).toBe(userId);
      expect(res2.headers['idempotent-replayed']).toBe('true');

      const res3 = await app.post('/v1/users')
        .set('Idempotency-Key', key)
        .send({ email: 'other@example.com', name: 'Other' });

      expect(res3.status).toBe(422);
    });
  });

  describe('GET /v1/users', () => {
    it('returns a paginated list of users', async () => {
      // Create a few users
      for (let i = 0; i < 5; i++) {
        await app.post('/v1/users').send({
          email: `u${i}@example.com`,
          name: `User ${i}`,
        });
      }

      const res = await app.get('/v1/users?limit=2');
      expect(res.status).toBe(200);
      expect(res.body.data).toHaveLength(2);
      expect(res.body.nextCursor).toBeDefined();
    });

    it('follows nextCursor to visit every user', async () => {
      for (let i = 0; i < 5; i++) {
        await app.post('/v1/users').send({
          email: `u${i}@example.com`,
          name: `User ${i}`,
        });
      }

      let users: any[] = [];
      let cursor: string | null = null;

      do {
        const res = await app.get(`/v1/users${cursor ? `?cursor=${cursor}` : ''}&limit=2`);
        users.push(...res.body.data);
        cursor = res.body.nextCursor;
      } while (cursor);

      expect(users).toHaveLength(5);
    });
  });

  describe('GET /v1/users/{userId}', () => {
    it('returns 200 for existing user', async () => {
      const resCreate = await app.post('/v1/users').send({
        email: 'get@example.com',
        name: 'Get User',
      });
      const id = resCreate.body.id;

      const res = await app.get(`/v1/users/${id}`);
      expect(res.status).toBe(200);
      expect(res.body.email).toBe('get@example.com');
    });

    it('returns 404 for non-existing user', async () => {
      const res = await app.get(`/v1/users/${uuidv4()}`);
      expect(res.status).toBe(404);
    });
  });

  describe('PATCH /v1/users/{userId}', () => {
    it('updates user fields and returns 200', async () => {
      const resCreate = await app.post('/v1/users').send({
        email: 'patch@example.com',
        name: 'Patch User',
      });
      const id = resCreate.body.id;

      const res = await app.patch(`/v1/users/${id}`).send({
        name: 'Updated Name',
      });
      expect(res.status).toBe(200);
      expect(res.body.name).toBe('Updated Name');
      expect(res.body.email).toBe('patch@example.com');
    });

    it('returns 409 if email updated to one that already exists', async () => {
      await app.post('/v1/users').send({ email: 'exists@example.com', name: 'Exists' });
      const resCreate = await app.post('/v1/users').send({ email: 'target@example.com', name: 'Target' });
      const id = resCreate.body.id;

      const res = await app.patch(`/v1/users/${id}`).send({
        email: 'exists@example.com',
      });
      expect(res.status).toBe(409);
    });

    it('returns 422 for empty patch', async () => {
      const resCreate = await app.post('/v1/users').send({ email: 'empty@example.com', name: 'Empty' });
      const id = resCreate.body.id;
      const res = await app.patch(`/v1/users/${id}`).send({});
      expect(res.status).toBe(422);
    });

    it('returns 404 for non-existing user', async () => {
      const res = await app.patch(`/v1/users/${uuidv4()}`).send({ name: 'New Name' });
      expect(res.status).toBe(404);
    });
  });

  describe('DELETE /v1/users/{userId}', () => {
    it('returns 204 and deletes user', async () => {
      const resCreate = await app.post('/v1/users').send({ email: 'del@example.com', name: 'Del' });
      const id = resCreate.body.id;

      const res = await app.delete(`/v1/users/${id}`);
      expect(res.status).toBe(204);

      const resGet = await app.get(`/v1/users/${id}`);
      expect(resGet.status).toBe(404);
    });

    it('returns 404 for non-existing user', async () => {
      const res = await app.delete(`/v1/users/${uuidv4()}`);
      expect(res.status).toBe(404);
    });
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { createApp } from '../src/app';
import { PROBLEM_CONTENT_TYPE } from '../src/lib/problem';

describe('Users API', () => {
  const app = createApp();

  const validUser = {
    email: 'test@example.com',
    name: 'Test User',
    role: 'member',
  };

  const validUser2 = {
    email: 'other@example.com',
    name: 'Other User',
    role: 'admin',
  };

  it('POST /v1/users creates a user', async () => {
    const res = await request(app)
      .post('/v1/users')
      .send(validUser);

    expect(res.status).toBe(201);
    expect(res.headers.location).toMatch(/\/v1\/users\/[a-f0-9-]{36}$/);
    expect(res.body).toMatchObject({
      id: expect.any(String),
      email: validUser.email,
      name: validUser.name,
      role: validUser.role,
      createdAt: expect.any(String),
      updatedAt: expect.any(String),
    });
  });

  it('POST /v1/users creates user with default role member', async () => {
    const res = await request(app)
      .post('/v1/users')
      .send({
        email: 'default@example.com',
        name: 'Default User',
      });

    expect(res.status).toBe(201);
    expect(res.body.role).toBe('member');
  });

  it('POST /v1/users returns 409 if email exists', async () => {
    const user = {
      email: 'duplicate@example.com',
      name: 'User 1',
    };
    await request(app).post('/v1/users').send(user);
    const res = await request(app).post('/v1/users').send(user);

    expect(res.status).toBe(409);
    expect(res.headers['content-type']).toContain(PROBLEM_CONTENT_TYPE);
    expect(res.body).toMatchObject({
      title: 'Conflict',
      status: 409,
    });
