  it('POST /v1/users honours Idempotency-Key', async () => {
    const user = {
      email: 'idempotent@example.com',
      name: 'Idempotent User',
    };
    const key = 'test-idempotency-key-1';

    const res1 = await request(app)
      .post('/v1/users')
      .set('Idempotency-Key', key)
      .send(user);

    expect(res1.status).toBe(201);
    const userId = res1.body.id;

    const res2 = await request(app)
      .post('/v1/users')
      .set('Idempotency-Key', key)
      .send(user);

    expect(res2.status).toBe(201);
    expect(res2.body.id).toBe(userId);
    expect(res2.headers['idempotent-replayed']).toBe('true');

    const res3 = await request(app)
      .post('/v1/users')
      .set('Idempotency-Key', key)
      .send({ ...user, name: 'Different Name' });

    expect(res3.status).toBe(422);
  });

